import{_ as e,o as r,c as o,a2 as a}from"./chunks/framework.mRCPFc5l.js";const p=JSON.parse('{"title":"Trigger","description":"The six triggers of a Flow in ApptiveGrid and when each one fits.","frontmatter":{"title":"Trigger","description":"The six triggers of a Flow in ApptiveGrid and when each one fits."},"headers":[],"relativePath":"en/flows/trigger.md","filePath":"en/flows/trigger.md","lastUpdated":1787319236000}'),n={name:"en/flows/trigger.md"};function s(i,t,d,l,h,g){return r(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="trigger" tabindex="-1">Trigger <a class="header-anchor" href="#trigger" aria-label="Permalink to &quot;Trigger&quot;">​</a></h1><p>The <strong>trigger</strong> is the event that starts a Flow. Every Flow has exactly one.</p><p>In the editor, the triggers live under the <strong>Trigger</strong> tab, under the question <em>When should the Flow start?</em>.</p><div class="warning custom-block"><p class="custom-block-title">The trigger is the most important decision</p><p>It determines not only <em>when</em> the Flow runs, but also <em>what data</em> is available to all subsequent steps. Changing it later usually means reconfiguring the following steps.</p></div><h2 id="the-six-triggers" tabindex="-1">The six triggers <a class="header-anchor" href="#the-six-triggers" aria-label="Permalink to &quot;The six triggers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Trigger</th><th>Description in the interface</th></tr></thead><tbody><tr><td><strong>New entry</strong></td><td><em>A new entry was added</em></td></tr><tr><td><strong>Entry was changed</strong></td><td><em>An existing entry was changed</em></td></tr><tr><td><strong>Entry via form</strong></td><td><em>New entry added via form</em></td></tr><tr><td><strong>Entry changed via form</strong></td><td><em>Existing entry changed via form</em></td></tr><tr><td><strong>Webhook</strong></td><td><em>Triggered by an external request</em></td></tr><tr><td><strong>Show page</strong></td><td><em>Start Flow and load page</em></td></tr></tbody></table><hr><h2 id="new-entry" tabindex="-1">New entry <a class="header-anchor" href="#new-entry" aria-label="Permalink to &quot;New entry&quot;">​</a></h2><p>Starts as soon as an entry is created in a Grid — <strong>regardless of where it comes from</strong>: from the table, from a form, via CSV import, or from another Flow.</p><p><strong>Configuration:</strong> select a Grid.</p><p><strong>Suited for:</strong> anything that should happen for every new record, no matter how it was created.</p><div class="warning custom-block"><p class="custom-block-title">CSV import also triggers it</p><p>Import 500 rows via CSV and you get 500 new entries. Before a large import, check whether a Flow is attached to it — otherwise 500 emails go out unintentionally.</p></div><hr><h2 id="entry-was-changed" tabindex="-1">Entry was changed <a class="header-anchor" href="#entry-was-changed" aria-label="Permalink to &quot;Entry was changed&quot;">​</a></h2><p>Starts when an existing entry is changed.</p><p><strong>Configuration:</strong> select a Grid and optionally a <strong>condition</strong> on a specific field.</p><div class="tip custom-block"><p class="custom-block-title">Always set a condition</p><p>Without a condition, the Flow starts on <em>every</em> change to <em>any</em> field — even a corrected typo in the name field. That produces a lot of unnecessary runs.</p><p>Restrict the trigger to the field that actually matters — such as <code>Status</code>.</p></div><h3 id="not-every-field-type-works-as-a-condition" tabindex="-1">Not every field type works as a condition <a class="header-anchor" href="#not-every-field-type-works-as-a-condition" aria-label="Permalink to &quot;Not every field type works as a condition&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field type</th><th>As a condition</th></tr></thead><tbody><tr><td>Text, Number, Date, Select, Currency, Checkmark, …</td><td>with value comparison</td></tr><tr><td>Files, Address, Geolocation, Signature, Created by, Internal Link</td><td>only &quot;has changed&quot;, without value comparison</td></tr><tr><td><strong>Use linked value</strong>, <strong>Calculate sum</strong>, <strong>Formula</strong></td><td><strong>not selectable</strong></td></tr><tr><td><strong>Created at</strong></td><td><strong>not selectable</strong></td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Calculated fields don&#39;t trigger</p><p>If a field of type <em>Use linked value</em>, <em>Calculate sum</em>, or <em>Formula</em> changes, it can&#39;t be used as a trigger. If you want to react to a calculation, you need to react to the underlying field instead.</p></div><hr><h2 id="entry-via-form" tabindex="-1">Entry via form <a class="header-anchor" href="#entry-via-form" aria-label="Permalink to &quot;Entry via form&quot;">​</a></h2><p>Starts when a specific <strong>form</strong> creates a new entry.</p><p><strong>Configuration:</strong> select a Grid and a form.</p><p><strong>Difference from &quot;New entry&quot;:</strong> this trigger reacts <strong>only</strong> to the chosen form, not to entries from other sources.</p><div class="tip custom-block"><p class="custom-block-title">The usual trigger for sign-ups</p><p>For confirmation emails, notifications, and approval processes, this is almost always the right trigger. It&#39;s more precise than <em>New entry</em> and won&#39;t fire accidentally on imports or manual data entry.</p></div><hr><h2 id="entry-changed-via-form" tabindex="-1">Entry changed via form <a class="header-anchor" href="#entry-changed-via-form" aria-label="Permalink to &quot;Entry changed via form&quot;">​</a></h2><p>Like the above, but for forms that edit an <strong>existing</strong> entry.</p><p><strong>Suited for:</strong> responses to a <a href="/en/formulare/vorausgefuellte-links">prefilled form link</a> — such as an acceptance or decline.</p><hr><h2 id="webhook" tabindex="-1">Webhook <a class="header-anchor" href="#webhook" aria-label="Permalink to &quot;Webhook&quot;">​</a></h2><p>Starts when an outside system sends a request. This is how you connect ApptiveGrid to any other tool.</p><p>The configuration explains itself in the interface under <em>Link to start the Flow</em>:</p><blockquote><p><em>To start the Flow, send a POST request to the following URL:</em></p></blockquote><p><strong>Send POST request</strong></p><blockquote><p><em>Send data in JSON format via a POST request to the link above to start the Flow.</em></p></blockquote><p><strong>Use as webhook</strong></p><blockquote><p><em>Enter the URL as a webhook in other services. This automatically starts the workflow when the corresponding service triggers the webhook.</em></p></blockquote><p><strong>Test webhook</strong></p><blockquote><p><em>You can test the webhook by sending a sample JSON payload:</em></p></blockquote><p>For this there&#39;s an input field <em>JSON payload</em> and the <strong>Test now</strong> button.</p><div class="danger custom-block"><p class="custom-block-title">The webhook URL is a credential</p><p>Anyone who knows the URL can start the Flow. Treat it like a password: not in public repositories, not in chats, not on slides.</p><p>You can see all active access points of a Space under <a href="/en/zusammenarbeit/externe-links">External links at a glance</a>.</p></div><p>→ <a href="/en/flows/webhook-trigger">Starting a Flow via webhook</a></p><hr><h2 id="show-page" tabindex="-1">Show page <a class="header-anchor" href="#show-page" aria-label="Permalink to &quot;Show page&quot;">​</a></h2><p>Starts when a <strong>page</strong> is opened and submitted. This is how a Flow begins with a user interface instead of a data event.</p><p>The interface explains:</p><blockquote><p><em>Use the link below to open the first page of our Flow. As soon as this page is submitted, the Flow will start.</em></p></blockquote><p>And on distributing it:</p><blockquote><p><em>You can also pass on this link, for example as a QR code for easy access, or link to it on your website or intranet.</em></p></blockquote><p><strong>Suited for:</strong> guided processes that begin with an input form — incident reports, orders, multi-stage applications.</p><div class="warning custom-block"><p class="custom-block-title">Two steps are both called &quot;Show page&quot;</p><p>The <strong>trigger</strong> <em>Show page</em> starts a Flow with a page. The <strong>action</strong> <em>Show page</em> displays a page in the middle of a Flow.</p><p>Both carry the same name in the interface. Pay attention to which tab you&#39;re in: <em>Trigger</em> or <em>Actions</em>.</p></div><hr><h2 id="which-trigger-fits" tabindex="-1">Which trigger fits? <a class="header-anchor" href="#which-trigger-fits" aria-label="Permalink to &quot;Which trigger fits?&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Goal</th><th>Trigger</th></tr></thead><tbody><tr><td>React to sign-ups via a specific form</td><td><strong>Entry via form</strong></td></tr><tr><td>React to every new record, regardless of source</td><td><strong>New entry</strong></td></tr><tr><td>React to a status change</td><td><strong>Entry was changed</strong> with a condition</td></tr><tr><td>Connect to an outside system</td><td><strong>Webhook</strong></td></tr><tr><td>Process that starts with an input form</td><td><strong>Show page</strong></td></tr><tr><td>Response to a link that was sent out</td><td><strong>Entry changed via form</strong></td></tr></tbody></table><h2 id="deprecated-triggers" tabindex="-1">Deprecated triggers <a class="header-anchor" href="#deprecated-triggers" aria-label="Permalink to &quot;Deprecated triggers&quot;">​</a></h2><p>Older Flows may contain triggers marked as <strong>deprecated</strong> in the editor. They keep working, but should be replaced with the current variants when you revise the Flow.</p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/en/flows/aktionen">Actions</a></li><li><a href="/en/flows/daten-zwischen-schritten">Data between steps</a></li><li><a href="/en/flows/testen">Testing Flows</a></li><li><a href="/en/grids/flow-button">Starting a Flow via button from an entry</a></li></ul>',60)])])}const m=e(n,[["render",s]]);export{p as __pageData,m as default};
